function before(date) {
 const tup = date.toISOString().substr(0, 10).split('-');
 return new Date(Number(tup[0]), Number(tup[1])-1, Number(tup[2]));
}
function after(date) {
 const timeOffsetInMS = date.getTimezoneOffset() * 60000;
 date.setTime(date.getTime() - timeOffsetInMS);
 return before(date);
}
for (const value of [Date.UTC(2019,8,20), Date.UTC(2019,8,1), 'Mon Sep 16 2019']) {
 console.log(JSON.stringify({value,before:before(new Date(value)).toDateString(),after:after(new Date(value)).toDateString()}));
}
